INSERT INTO user_profiles (id, "userId", age, gender, "heightCm", goal, "activityLevel", "experienceLevel", "preferredTrainingDays", "availableEquipment", injuries, "currentWeight", "targetWeight", "createdAt", "updatedAt", "isPT") VALUES
  ('seed_profile_001', 'seed_usr_cut_001', 27, 'MALE', 172.0, 'WEIGHT_LOSS', 'MODERATELY_ACTIVE', 'BEGINNER', NULL, NULL, NULL, 92.0, 78.0, '2026-02-01 08:00:00', '2026-04-08 09:00:00', FALSE),
