  ('seed_nl_027', 'seed_usr_gain_001', '2026-04-05 19:30:00', 'DINNER', 'Cá ngừ áp chảo + couscous + rau củ', 710, 50, 63, 19, 'Giữ protein cao, đủ carb phục hồi.', '2026-04-05 19:30:00', '2026-04-05 19:30:00')
INSERT INTO workout_plans (id, user_id, name, description, goal, duration, days_per_week, plan, created_at, updated_at) VALUES
  ('seed_plan_001', 'seed_usr_cut_001', '8-Week Fat Loss Foundation', 'Giáo án 8 tuần cho người mới, ưu tiên toàn thân, đi bộ và thói quen ăn uống ổn định.', 'fat_loss', 8, 3, '{"phase": "foundation", "summary": "3 buổi full body/tuần + mục tiêu 7000-9000 bước/ngày.", "progression": "Khi đạt ngưỡng reps trên của mọi set với kỹ thuật tốt, tăng tải 2.5-5%.", "days": [{"day": 1, "focus": "Full Body A", "exercises": [{"name": "Goblet Squat", "sets": "3", "reps": "10-12"}, {"name": "Push-Up", "sets": "3", "reps": "8-10"}, {"name": "Lat Pulldown", "sets": "3", "reps": "10-12"}, {"name": "Glute Bridge", "sets": "3", "reps": "12-15"}, {"name": "Front Plank", "sets": "3", "duration_sec": "30-40"}]}, {"day": 2, "focus": "Full Body B", "exercises": [{"name": "Dumbbell Romanian Deadlift", "sets": "3", "reps": "8-10"}, {"name": "Step-Up", "sets": "3", "reps": "10/leg"}, {"name": "Seated Cable Row", "sets": "3", "reps": "10-12"}, {"name": "Seated Dumbbell Shoulder Press", "sets": "3", "reps": "8-10"}, {"name": "Dead Bug", "sets": "3", "reps": "10/side"}]}, {"day": 3, "focus": "Conditioning + Mobility", "exercises": [{"name": "Jump Rope", "sets": "5", "duration_sec": "45-60"}, {"name": "Mountain Climber", "sets": "4", "duration_sec": "20-30"}, {"name": "Resistance Band Pull-Apart", "sets": "3", "reps": "15"}, {"name": "Child''s Pose", "sets": "2", "duration_sec": "45"}]}], "nutrition_notes": ["Ưu tiên protein mỗi bữa", "Giảm đồ uống có đường", "Ăn rau trong ít nhất 2 bữa chính/ngày"]}'::jsonb, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_plan_002', 'seed_usr_recomp_001', '6-Week Recomp Lower Emphasis', 'Chương trình 6 tuần cho người đã có nền tảng nhẹ, tập trung thân dưới và giữ vóc dáng.', 'recomp', 6, 3, '{"phase": "recomposition", "summary": "2 buổi lower + 1 buổi upper/tuần, cardio ngắn sau tập 1-2 lần.", "progression": "Tăng reps trước, tăng tải sau. Giữ RPE khoảng 7-8 ở bài chính.", "days": [{"day": 1, "focus": "Lower Glutes", "exercises": [{"name": "Barbell Hip Thrust", "sets": "4", "reps": "8"}, {"name": "Dumbbell Romanian Deadlift", "sets": "4", "reps": "10"}, {"name": "Walking Lunge", "sets": "3", "reps": "10/leg"}, {"name": "Leg Curl", "sets": "3", "reps": "12"}, {"name": "Side Plank", "sets": "3", "duration_sec": "30-40"}]}, {"day": 2, "focus": "Upper Balance", "exercises": [{"name": "Incline Dumbbell Press", "sets": "4", "reps": "8"}, {"name": "One-Arm Dumbbell Row", "sets": "4", "reps": "10/side"}, {"name": "Face Pull", "sets": "3", "reps": "15"}, {"name": "Dumbbell Lateral Raise", "sets": "3", "reps": "15"}, {"name": "Dead Bug", "sets": "3", "reps": "10/side"}]}, {"day": 3, "focus": "Lower + Conditioning", "exercises": [{"name": "Goblet Squat", "sets": "3", "reps": "12"}, {"name": "Step-Up", "sets": "3", "reps": "12/leg"}, {"name": "Kettlebell Swing", "sets": "6", "duration_sec": "20"}, {"name": "Mountain Climber", "sets": "4", "duration_sec": "30"}]}], "nutrition_notes": ["Duy trì protein cao", "Carb quanh buổi tập", "Kiểm tra số đo và ảnh mỗi 2 tuần"]}'::jsonb, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_plan_003', 'seed_usr_gain_001', '12-Week Hypertrophy Push Pull Legs', 'Giáo án 12 tuần tăng cơ cho người trung cấp, nhấn mạnh progressive overload và kiểm soát volume.', 'muscle_gain', 12, 5, '{"phase": "hypertrophy", "summary": "PPL 5 buổi/tuần với 1-2 buổi phụ, surplus nhẹ và ngủ đủ.", "progression": "Ở bài compound, tăng 2.5-5 kg khi hoàn thành mức reps mục tiêu ở tất cả set. Bài phụ tăng 1-2 reps trước.", "days": [{"day": 1, "focus": "Push Heavy", "exercises": [{"name": "Barbell Bench Press", "sets": "4", "reps": "5-6"}, {"name": "Incline Dumbbell Press", "sets": "4", "reps": "8"}, {"name": "Seated Dumbbell Shoulder Press", "sets": "4", "reps": "8"}, {"name": "Cable Chest Fly", "sets": "3", "reps": "12"}, {"name": "Triceps Rope Pushdown", "sets": "3", "reps": "12"}]}, {"day": 2, "focus": "Pull Heavy", "exercises": [{"name": "Barbell Bent-Over Row", "sets": "4", "reps": "6-8"}, {"name": "Lat Pulldown", "sets": "4", "reps": "8-10"}, {"name": "Seated Cable Row", "sets": "3", "reps": "10"}, {"name": "Face Pull", "sets": "3", "reps": "15"}, {"name": "Hammer Curl", "sets": "3", "reps": "12"}]}, {"day": 3, "focus": "Legs Heavy", "exercises": [{"name": "Barbell Back Squat", "sets": "5", "reps": "5"}, {"name": "Romanian Deadlift", "sets": "4", "reps": "6"}, {"name": "Leg Press", "sets": "3", "reps": "12"}, {"name": "Leg Curl", "sets": "3", "reps": "12"}, {"name": "Standing Calf Raise", "sets": "4", "reps": "15"}]}], "nutrition_notes": ["Surplus nhẹ 200-300 kcal", "Protein phân đều 3-5 bữa", "Theo dõi cân nặng trung bình tuần"]}'::jsonb, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_plan_004', 'seed_usr_cut_001', '4-Week Home Dumbbell Reset', 'Kế hoạch ngắn cho người tập ở nhà với dumbbell và bodyweight.', 'general_fitness', 4, 4, '{"phase": "home_training", "summary": "4 buổi/tuần, mỗi buổi 35-45 phút.", "progression": "Thêm 1-2 reps hoặc tăng nhịp chậm ở eccentric khi chưa có tạ nặng hơn.", "days": [{"day": 1, "focus": "Upper", "exercises": [{"name": "Incline Push-Up", "sets": "4", "reps": "10-15"}, {"name": "One-Arm Dumbbell Row", "sets": "4", "reps": "12/side"}, {"name": "Dumbbell Lateral Raise", "sets": "3", "reps": "15"}]}, {"day": 2, "focus": "Lower", "exercises": [{"name": "Goblet Squat", "sets": "4", "reps": "12"}, {"name": "Dumbbell Romanian Deadlift", "sets": "4", "reps": "12"}, {"name": "Glute Bridge", "sets": "3", "reps": "20"}]}, {"day": 3, "focus": "Core + Conditioning", "exercises": [{"name": "Front Plank", "sets": "3", "duration_sec": "40"}, {"name": "Mountain Climber", "sets": "5", "duration_sec": "30"}, {"name": "Jump Rope", "sets": "5", "duration_sec": "60"}]}]}'::jsonb, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_plan_005', 'seed_usr_recomp_001', '6-Week Mobility & Core Restore', 'Kế hoạch phục hồi chủ động cho giai đoạn stress cao hoặc mới quay lại tập.', 'recovery_mobility', 6, 3, '{"phase": "restore", "summary": "3 buổi/tuần, nhấn mạnh mobility, core và bước đi mỗi ngày.", "progression": "Tăng thời gian giữ và biên độ có kiểm soát, không tăng độ khó quá nhanh.", "days": [{"day": 1, "focus": "Core Stability", "exercises": [{"name": "Dead Bug", "sets": "3", "reps": "8/side"}, {"name": "Bird Dog", "sets": "3", "reps": "8/side"}, {"name": "Front Plank", "sets": "3", "duration_sec": "20-30"}]}, {"day": 2, "focus": "Mobility", "exercises": [{"name": "Cat-Cow", "sets": "2", "reps": "8"}, {"name": "Thoracic Rotation", "sets": "2", "reps": "8/side"}, {"name": "Hip Flexor Stretch", "sets": "2", "duration_sec": "30/side"}, {"name": "Hamstring Stretch", "sets": "2", "duration_sec": "30/side"}]}, {"day": 3, "focus": "Light Full Body", "exercises": [{"name": "Bodyweight Squat", "sets": "3", "reps": "12"}, {"name": "Resistance Band Pull-Apart", "sets": "3", "reps": "15"}, {"name": "Child''s Pose", "sets": "2", "duration_sec": "45"}]}]}'::jsonb, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_plan_006', 'seed_usr_gain_001', '8-Week Strength Base 4-Day', 'Chương trình 4 buổi để củng cố sức mạnh nền trước khi vào block hypertrophy cao hơn.', 'strength_base', 8, 4, '{"phase": "strength", "summary": "Upper/Lower 4 buổi, compound làm chính, volume vừa phải.", "progression": "Mục tiêu tăng tạ đều nhưng giữ ít nhất 1-2 reps dự trữ ở đa số set.", "days": [{"day": 1, "focus": "Upper 1", "exercises": [{"name": "Barbell Bench Press", "sets": "5", "reps": "5"}, {"name": "Barbell Bent-Over Row", "sets": "5", "reps": "5"}, {"name": "Face Pull", "sets": "3", "reps": "15"}]}, {"day": 2, "focus": "Lower 1", "exercises": [{"name": "Barbell Back Squat", "sets": "5", "reps": "5"}, {"name": "Romanian Deadlift", "sets": "4", "reps": "6"}, {"name": "Standing Calf Raise", "sets": "4", "reps": "12"}]}, {"day": 3, "focus": "Upper 2", "exercises": [{"name": "Seated Dumbbell Shoulder Press", "sets": "4", "reps": "6-8"}, {"name": "Lat Pulldown", "sets": "4", "reps": "8"}, {"name": "Hammer Curl", "sets": "3", "reps": "10"}]}, {"day": 4, "focus": "Lower 2", "exercises": [{"name": "Leg Press", "sets": "4", "reps": "10"}, {"name": "Walking Lunge", "sets": "3", "reps": "8/leg"}, {"name": "Front Plank", "sets": "3", "duration_sec": "45"}]}]}'::jsonb, '2026-04-08 09:00:00', '2026-04-08 09:00:00')
INSERT INTO conversations (id, user_id, question, answer, model_used, response_time, relevance, relevance_explanation, prompt_tokens, completion_tokens, total_tokens, cost, feedback, feedback_timestamp, created_at) VALUES
  ('seed_conv_001', NULL, 'Progressive overload là gì?', 'Progressive overload là nguyên tắc tăng dần áp lực tập luyện theo thời gian để cơ thể tiếp tục thích nghi. Bạn có thể tăng tạ, thêm reps, thêm set, cải thiện kỹ thuật hoặc rút ngắn thời gian nghỉ, nhưng nên thay đổi có kiểm soát và vẫn giữ form chuẩn.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:00:00'),
  ('seed_conv_002', NULL, 'Người mới nên tập mấy buổi mỗi tuần?', 'Người mới thường phù hợp với 2-4 buổi kháng lực mỗi tuần. Điều quan trọng không chỉ là số buổi mà là tổng khối lượng tập vừa đủ, thời gian phục hồi và khả năng duy trì đều trong nhiều tuần.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:05:00'),
  ('seed_conv_003', NULL, 'Có cần khởi động trước khi tập không?', 'Có. Khởi động giúp tăng nhiệt cơ thể, cải thiện phạm vi chuyển động và chuẩn bị hệ thần kinh cho bài chính. Một buổi khởi động tốt thường gồm 5-10 phút vận động nhẹ, 1-2 bài mobility liên quan và vài set làm quen với tải thấp.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:10:00'),
  ('seed_conv_004', NULL, 'DOMS có phải là dấu hiệu của buổi tập tốt?', 'Không hẳn. DOMS chỉ là đau mỏi cơ xuất hiện sau tập, thường do cơ thể chưa quen mức tải hoặc biên độ mới. Một buổi tập tốt được đánh giá tốt hơn qua tiến bộ dài hạn về hiệu suất, kỹ thuật và khả năng phục hồi, không phải chỉ bằng cảm giác đau.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:15:00'),
  ('seed_conv_005', NULL, 'Giảm mỡ có cần bỏ hoàn toàn tinh bột không?', 'Không cần. Giảm mỡ chủ yếu phụ thuộc vào việc duy trì mức năng lượng nạp vào thấp hơn mức tiêu hao trong thời gian đủ dài. Tinh bột vẫn hữu ích cho hiệu suất tập luyện và phục hồi; quan trọng là chọn khẩu phần phù hợp và ưu tiên nguồn thực phẩm ít chế biến.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:20:00'),
  ('seed_conv_006', NULL, 'Protein nên chia như thế nào trong ngày?', 'Thực tế hơn cả là phân bổ protein khá đều vào 3-5 bữa trong ngày thay vì dồn toàn bộ vào một bữa. Cách này giúp dễ đạt tổng lượng protein mục tiêu và hỗ trợ phục hồi cơ bắp tốt hơn.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:25:00'),
  ('seed_conv_007', NULL, 'Nên nghỉ bao lâu giữa các set?', 'Bài compound nặng thường cần nghỉ khoảng 2-3 phút để giữ hiệu suất. Bài phụ hoặc isolation thường nghỉ ngắn hơn, khoảng 45-90 giây. Mục tiêu là nghỉ đủ để giữ chất lượng set tiếp theo, không chỉ nghỉ theo thói quen.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:30:00'),
  ('seed_conv_008', NULL, 'Khi nào nên deload?', 'Deload thường phù hợp khi bạn tích lũy mệt mỏi rõ rệt: hiệu suất giảm liên tiếp, đau mỏi kéo dài, khó ngủ hoặc cảm giác nặng nề bất thường. Deload không có nghĩa là nghỉ hẳn; bạn có thể giảm tải, giảm set hoặc giảm cường độ trong khoảng 5-7 ngày.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:35:00'),
  ('seed_conv_009', NULL, 'Tập cardio có làm mất cơ không?', 'Cardio không tự động làm mất cơ. Vấn đề thường đến từ việc cardio quá nhiều trong khi ăn quá ít, ngủ kém và vẫn cố duy trì khối lượng tập tạ cao. Khi phối hợp hợp lý, cardio còn giúp cải thiện tim mạch và khả năng phục hồi chung.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:40:00'),
  ('seed_conv_010', NULL, 'Creatine có đáng dùng không?', 'Creatine monohydrate là một trong những supplement được nghiên cứu nhiều nhất cho hiệu suất sức mạnh và công suất ngắn hạn. Tuy nhiên, supplement chỉ là phần nhỏ; nền tảng vẫn là tập luyện đúng, ăn đủ và ngủ đủ.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:45:00'),
  ('seed_conv_011', NULL, 'Ngủ ảnh hưởng thế nào đến tăng cơ và giảm mỡ?', 'Ngủ kém thường làm giảm hiệu suất tập luyện, tăng cảm giác đói, làm việc phục hồi cơ bắp kém hơn và khiến việc bám kế hoạch ăn uống khó hơn. Với đa số người trưởng thành, ngủ đều và đủ giờ là một biến số rất quan trọng nhưng hay bị xem nhẹ.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:50:00'),
  ('seed_conv_012', NULL, 'Khi nào nên dừng bài tập vì đau?', 'Nếu chỉ là mỏi cơ nhẹ và kỹ thuật vẫn ổn, bạn có thể tiếp tục có kiểm soát. Nhưng nếu xuất hiện đau nhói, đau tăng theo từng rep, tê lan hoặc cảm giác mất ổn định, nên dừng bài tập đó và cân nhắc đánh giá chuyên môn y tế nếu triệu chứng kéo dài.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:55:00')
INSERT INTO user_profiles (id, "userId", age, gender, "heightCm", goal, "activityLevel", "experienceLevel", "preferredTrainingDays", "availableEquipment", injuries, "currentWeight", "targetWeight", "createdAt", "updatedAt", "isPT", email, "firstName", "lastName") VALUES
  ('seed_profile_001', 'seed_usr_cut_001', 27, 'MALE', 172.0, 'WEIGHT_LOSS', 'MODERATELY_ACTIVE', 'BEGINNER', NULL, NULL, NULL, 92.0, 78.0, '2026-02-01 08:00:00', '2026-04-08 09:00:00', FALSE, 'minh.demo@gymcoach.local', 'Minh', 'Tran'),
  ('seed_profile_002', 'seed_usr_recomp_001', 30, 'FEMALE', 160.0, 'MAINTENANCE', 'LIGHTLY_ACTIVE', 'INTERMEDIATE', NULL, NULL, NULL, 58.0, 56.0, '2026-02-01 08:10:00', '2026-04-08 09:00:00', FALSE, 'lan.demo@gymcoach.local', 'Lan', 'Nguyen'),
  ('seed_profile_003', 'seed_usr_gain_001', 24, 'MALE', 178.0, 'MUSCLE_GAIN', 'VERY_ACTIVE', 'INTERMEDIATE', NULL, NULL, NULL, 74.0, 78.0, '2026-02-01 08:20:00', '2026-04-08 09:00:00', FALSE, 'khoa.demo@gymcoach.local', 'Khoa', 'Le')
INSERT INTO inbody_entries (id, user_id, date, weight, height, bmi, bmr, body_fat, body_fat_pct, muscle_mass, right_arm_muscle, left_arm_muscle, trunk_muscle, right_leg_muscle, left_leg_muscle, right_arm_fat, left_arm_fat, trunk_fat, right_leg_fat, left_leg_fat, status, notes, created_at, updated_at) VALUES
  ('seed_inbody_001', 'seed_usr_cut_001', '2026-02-03 07:30:00', 92.0, 172.0, 31.1, 1825.0, 28.5, 31.0, 34.8, 3.4, 3.3, 27.1, 9.3, 9.2, 1.9, 1.9, 14.6, 4.7, 4.7, 'manual', 'Điểm bắt đầu: thừa cân, ưu tiên giảm mỡ, xây lại thói quen vận động.', '2026-02-03 07:35:00', '2026-02-03 07:35:00'),
  ('seed_inbody_002', 'seed_usr_cut_001', '2026-03-03 07:30:00', 88.6, 172.0, 29.9, 1796.0, 25.9, 29.2, 34.6, 3.4, 3.3, 27.0, 9.3, 9.2, 1.8, 1.8, 13.0, 4.2, 4.2, 'manual', 'Giảm cân ổn định, khối cơ gần như giữ được.', '2026-03-03 07:35:00', '2026-03-03 07:35:00'),
  ('seed_inbody_003', 'seed_usr_cut_001', '2026-04-03 07:30:00', 86.9, 172.0, 29.4, 1782.0, 24.3, 28.0, 34.7, 3.4, 3.3, 27.1, 9.3, 9.2, 1.7, 1.7, 12.1, 4.0, 4.0, 'manual', 'Tiếp tục giảm mỡ, sức bền cải thiện rõ.', '2026-04-03 07:35:00', '2026-04-03 07:35:00'),
  ('seed_inbody_004', 'seed_usr_recomp_001', '2026-02-05 18:00:00', 58.0, 160.0, 22.7, 1315.0, 13.2, 22.8, 22.9, 2.0, 2.0, 18.0, 6.0, 5.9, 0.9, 0.9, 6.4, 2.5, 2.5, 'manual', 'Mục tiêu giữ cân, tăng độ săn chắc và sức mạnh thân dưới.', '2026-02-05 18:05:00', '2026-02-05 18:05:00'),
  ('seed_inbody_005', 'seed_usr_recomp_001', '2026-03-05 18:00:00', 57.7, 160.0, 22.5, 1322.0, 12.6, 21.8, 23.4, 2.1, 2.0, 18.2, 6.1, 6.0, 0.8, 0.8, 6.1, 2.4, 2.4, 'manual', 'Khối cơ tăng nhẹ, tỷ lệ mỡ giảm.', '2026-03-05 18:05:00', '2026-03-05 18:05:00'),
  ('seed_inbody_006', 'seed_usr_recomp_001', '2026-04-05 18:00:00', 57.9, 160.0, 22.6, 1327.0, 12.4, 21.4, 23.8, 2.1, 2.1, 18.4, 6.2, 6.1, 0.8, 0.8, 6.0, 2.4, 2.4, 'manual', 'Recomp tốt, vòng eo giảm nhưng hiệu suất buổi tập tăng.', '2026-04-05 18:05:00', '2026-04-05 18:05:00'),
  ('seed_inbody_007', 'seed_usr_gain_001', '2026-02-07 06:45:00', 74.0, 178.0, 23.4, 1710.0, 10.9, 14.8, 35.9, 3.6, 3.5, 28.5, 9.7, 9.6, 0.8, 0.8, 5.2, 2.0, 2.0, 'manual', 'Nền tảng tốt, mục tiêu bulk sạch và tăng sức mạnh.', '2026-02-07 06:50:00', '2026-02-07 06:50:00'),
  ('seed_inbody_008', 'seed_usr_gain_001', '2026-03-07 06:45:00', 75.4, 178.0, 23.8, 1732.0, 11.3, 15.0, 36.6, 3.7, 3.6, 28.9, 9.8, 9.7, 0.8, 0.8, 5.4, 2.1, 2.1, 'manual', 'Khối cơ tăng khá tốt, mỡ tăng ít.', '2026-03-07 06:50:00', '2026-03-07 06:50:00'),
  ('seed_inbody_009', 'seed_usr_gain_001', '2026-04-07 06:45:00', 76.3, 178.0, 24.1, 1744.0, 11.7, 15.3, 37.1, 3.7, 3.7, 29.2, 9.9, 9.8, 0.9, 0.9, 5.6, 2.2, 2.2, 'manual', 'Tiếp tục tăng cơ, cần theo dõi surplus để không tăng mỡ quá nhanh.', '2026-04-07 06:50:00', '2026-04-07 06:50:00')
INSERT INTO exercises (id, exercise_name, type_of_activity, type_of_equipment, body_part, type, muscle_groups_activated, instructions, video_url, created_at, updated_at) VALUES
  ('seed_ex_001', 'Push-Up', 'STRENGTH', 'BODYWEIGHT', 'UPPER_BODY', 'PUSH', ARRAY['chest', 'triceps', 'front delts'], 'Vào tư thế plank cao, siết core, hạ ngực có kiểm soát đến gần sàn rồi đẩy lên. Giữ thân người thành một đường thẳng, không võng lưng.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_002', 'Incline Push-Up', 'STRENGTH', 'BODYWEIGHT', 'UPPER_BODY', 'PUSH', ARRAY['chest', 'triceps', 'front delts'], 'Đặt tay lên ghế hoặc bục cao, thân người thẳng, hạ ngực về mép ghế rồi đẩy lên. Phù hợp người mới tập hoặc đang cần giảm độ khó.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_003', 'Barbell Bench Press', 'STRENGTH', 'BARBELL', 'UPPER_BODY', 'PUSH', ARRAY['chest', 'triceps', 'front delts'], 'Nằm trên ghế phẳng, kéo vai về sau, hạ thanh đòn xuống vùng giữa ngực rồi đẩy lên. Bàn chân giữ chắc trên sàn và không bật hông.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_004', 'Incline Dumbbell Press', 'STRENGTH', 'DUMBBELLS', 'UPPER_BODY', 'PUSH', ARRAY['upper chest', 'triceps', 'front delts'], 'Ngồi trên ghế nghiêng 30–45 độ, hạ tạ xuống cạnh ngực trên rồi đẩy lên theo vòng cung nhẹ. Không để vai nhô ra trước quá mức.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_005', 'Seated Dumbbell Shoulder Press', 'STRENGTH', 'DUMBBELLS', 'UPPER_BODY', 'PUSH', ARRAY['shoulders', 'triceps'], 'Ngồi thẳng lưng, bắt đầu với tạ ngang tai, đẩy lên qua đầu rồi hạ xuống có kiểm soát. Không ngửa lưng quá mạnh để tránh ăn vào lưng dưới.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_006', 'Dumbbell Lateral Raise', 'STRENGTH', 'DUMBBELLS', 'UPPER_BODY', 'PUSH', ARRAY['side delts', 'upper traps'], 'Giữ khuỷu hơi cong, nâng tạ sang hai bên đến ngang vai rồi hạ chậm. Không vung người để lấy đà.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_007', 'Cable Chest Fly', 'STRENGTH', 'CABLE', 'UPPER_BODY', 'PUSH', ARRAY['chest', 'front delts'], 'Đứng giữa máy cáp, khép hai tay trước ngực theo vòng cung nhẹ rồi mở ra chậm rãi. Giữ ngực mở và khuỷu hơi cong suốt bài.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_008', 'Triceps Rope Pushdown', 'STRENGTH', 'CABLE', 'UPPER_BODY', 'PUSH', ARRAY['triceps'], 'Ép khuỷu sát thân, đẩy dây xuống cho đến khi tay duỗi gần hết rồi trở về vị trí đầu. Không nhún vai hoặc dùng lưng để kéo.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_009', 'One-Arm Dumbbell Row', 'STRENGTH', 'DUMBBELLS', 'UPPER_BODY', 'PULL', ARRAY['lats', 'mid back', 'rear delts', 'biceps'], 'Chống một tay lên ghế, lưng phẳng, kéo tạ về gần hông rồi hạ chậm. Tập trung kéo bằng lưng thay vì giật bằng tay.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_010', 'Barbell Bent-Over Row', 'STRENGTH', 'BARBELL', 'UPPER_BODY', 'PULL', ARRAY['lats', 'mid back', 'rear delts', 'biceps'], 'Gập hông, giữ cột sống trung lập, kéo thanh đòn về bụng dưới rồi hạ xuống có kiểm soát. Không ngóc người lên quá nhiều trong lúc kéo.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_011', 'Lat Pulldown', 'STRENGTH', 'MACHINE', 'UPPER_BODY', 'PULL', ARRAY['lats', 'upper back', 'biceps'], 'Kéo thanh xuống vùng ngực trên, ép bả vai xuống và ra sau, sau đó đưa tay lên chậm. Không ngả người quá mạnh để lấy đà.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_012', 'Seated Cable Row', 'STRENGTH', 'CABLE', 'UPPER_BODY', 'PULL', ARRAY['mid back', 'lats', 'rear delts', 'biceps'], 'Ngồi thẳng, kéo tay cầm về rốn, siết lưng giữa rồi duỗi tay chậm. Tránh cuộn vai về trước ở cuối biên độ.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_013', 'Face Pull', 'STRENGTH', 'CABLE', 'UPPER_BODY', 'PULL', ARRAY['rear delts', 'upper back', 'rotator cuff'], 'Kéo dây về ngang mặt, khuỷu tay mở, siết vai sau ở cuối động tác. Đây là bài tốt để cân bằng nhóm cơ vai trước–sau.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_014', 'Pull-Up', 'STRENGTH', 'BODYWEIGHT', 'UPPER_BODY', 'PULL', ARRAY['lats', 'upper back', 'biceps', 'core'], 'Treo người chủ động, kéo ngực lên gần xà rồi hạ xuống có kiểm soát. Nếu chưa đủ sức, có thể thay bằng band-assisted pull-up hoặc lat pulldown.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_015', 'Dumbbell Bicep Curl', 'STRENGTH', 'DUMBBELLS', 'UPPER_BODY', 'PULL', ARRAY['biceps', 'forearms'], 'Giữ khuỷu sát thân, cuốn tạ lên rồi hạ xuống chậm. Hạn chế lắc người để đảm bảo bắp tay làm việc chính.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_016', 'Hammer Curl', 'STRENGTH', 'DUMBBELLS', 'UPPER_BODY', 'PULL', ARRAY['biceps', 'brachialis', 'forearms'], 'Giữ lòng bàn tay hướng vào nhau, cuốn tạ lên rồi hạ chậm. Bài này hỗ trợ tăng lực kéo và độ dày cánh tay.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_017', 'Bodyweight Squat', 'STRENGTH', 'BODYWEIGHT', 'LOWER_BODY', 'PUSH', ARRAY['quadriceps', 'glutes', 'adductors', 'core'], 'Đẩy hông ra sau, hạ người xuống đến mức phù hợp rồi đứng lên. Giữ ngực mở, gối đi theo hướng mũi chân.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_018', 'Goblet Squat', 'STRENGTH', 'DUMBBELLS', 'LOWER_BODY', 'PUSH', ARRAY['quadriceps', 'glutes', 'core'], 'Ôm tạ trước ngực, squat xuống với thân người ổn định rồi đứng lên. Đây là bài rất tốt để học kỹ thuật squat cho người mới.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_019', 'Barbell Back Squat', 'STRENGTH', 'BARBELL', 'LOWER_BODY', 'PUSH', ARRAY['quadriceps', 'glutes', 'adductors', 'core'], 'Đặt thanh đòn chắc trên lưng trên, hít sâu, ngồi xuống theo đường gối–hông tự nhiên rồi đứng lên mạnh mẽ. Giữ cột sống trung lập trong toàn bộ bài.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_020', 'Leg Press', 'STRENGTH', 'MACHINE', 'LOWER_BODY', 'PUSH', ARRAY['quadriceps', 'glutes'], 'Đặt chân trên bàn đạp ở vị trí ổn định, hạ tạ đến biên độ kiểm soát được rồi đẩy lên. Không khóa cứng gối ở cuối động tác.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_021', 'Walking Lunge', 'STRENGTH', 'BODYWEIGHT', 'LOWER_BODY', 'PUSH', ARRAY['quadriceps', 'glutes', 'hamstrings', 'core'], 'Bước dài vừa phải, hạ gối sau gần sàn rồi đẩy người lên để bước tiếp. Giữ thân người thẳng và kiểm soát trục gối.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_022', 'Step-Up', 'STRENGTH', 'DUMBBELLS', 'LOWER_BODY', 'PUSH', ARRAY['quadriceps', 'glutes', 'calves'], 'Đặt một chân lên bục, dồn lực qua gót để đứng lên rồi xuống chậm. Hạn chế dùng đà từ chân dưới sàn.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_023', 'Romanian Deadlift', 'STRENGTH', 'BARBELL', 'LOWER_BODY', 'PULL', ARRAY['hamstrings', 'glutes', 'lower back'], 'Đẩy hông ra sau, giữ lưng thẳng, hạ thanh sát đùi cho đến khi cảm nhận căng gân kheo rồi đứng lên. Không biến bài thành squat nửa vời.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_024', 'Dumbbell Romanian Deadlift', 'STRENGTH', 'DUMBBELLS', 'LOWER_BODY', 'PULL', ARRAY['hamstrings', 'glutes', 'lower back'], 'Giữ hai tạ trước đùi, gập hông ra sau và hạ tạ xuống dọc thân rồi đứng lên. Cảm nhận kéo căng ở mặt sau đùi.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_025', 'Leg Curl', 'STRENGTH', 'MACHINE', 'LOWER_BODY', 'PULL', ARRAY['hamstrings'], 'Co gót chân về phía mông rồi hạ chậm. Không giật tạ ở đầu bài để tránh mất căng cơ.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_026', 'Standing Calf Raise', 'STRENGTH', 'MACHINE', 'LOWER_BODY', 'PUSH', ARRAY['calves'], 'Nâng gót chân lên cao, giữ ngắn ở đỉnh rồi hạ xuống hết biên độ. Thực hiện chậm để tăng cảm nhận bắp chuối.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_027', 'Glute Bridge', 'STRENGTH', 'BODYWEIGHT', 'LOWER_BODY', 'PUSH', ARRAY['glutes', 'hamstrings', 'core'], 'Nằm ngửa, co gối, đẩy hông lên cao bằng gót chân rồi hạ xuống chậm. Tránh ưỡn lưng dưới ở đỉnh động tác.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_028', 'Barbell Hip Thrust', 'STRENGTH', 'BARBELL', 'LOWER_BODY', 'PUSH', ARRAY['glutes', 'hamstrings'], 'Tựa lưng trên ghế, đặt thanh đòn trên hông, đẩy hông lên đến khi thân người song song sàn rồi hạ chậm. Giữ cằm hơi thu và xương sườn không bật lên.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_029', 'Front Plank', 'STRENGTH', 'BODYWEIGHT', 'CORE', 'HOLD', ARRAY['abs', 'obliques', 'glutes', 'shoulders'], 'Chống khuỷu tay dưới vai, siết bụng và mông, giữ thân người thẳng. Không để hông võng hoặc dựng quá cao.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_030', 'Side Plank', 'STRENGTH', 'BODYWEIGHT', 'CORE', 'HOLD', ARRAY['obliques', 'glutes', 'shoulders'], 'Chống khuỷu tay dưới vai, nâng hông lên và giữ cơ thể thành đường thẳng. Bài này tốt cho ổn định thân bên.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_031', 'Dead Bug', 'STRENGTH_MOBILITY', 'BODYWEIGHT', 'CORE', 'HOLD', ARRAY['deep core', 'hip flexors', 'shoulder stabilizers'], 'Nằm ngửa, ép lưng dưới xuống sàn, duỗi tay chân đối bên chậm rãi rồi trở về. Giữ bụng siết suốt bài.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_032', 'Bird Dog', 'STRENGTH_MOBILITY', 'BODYWEIGHT', 'CORE', 'HOLD', ARRAY['deep core', 'glutes', 'lower back'], 'Ở tư thế bò bốn điểm, duỗi tay và chân đối bên, giữ thân ổn định rồi đổi bên. Tránh xoay hông sang hai bên.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_033', 'Hanging Knee Raise', 'STRENGTH', 'BODYWEIGHT', 'CORE', 'PULL', ARRAY['lower abs', 'hip flexors', 'grip'], 'Treo người trên xà, kéo gối lên có kiểm soát rồi hạ chậm. Không vung người quá mạnh.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_034', 'Russian Twist', 'STRENGTH', 'MEDICINE_BALL', 'CORE', 'HOLD', ARRAY['obliques', 'abs'], 'Ngồi ngả người nhẹ, xoay thân sang hai bên với biên độ kiểm soát. Giữ cột sống dài, không gù lưng.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_035', 'Cat-Cow', 'MOBILITY', 'BODYWEIGHT', 'CORE', 'STRETCH', ARRAY['spine', 'core', 'shoulders'], 'Ở tư thế bò, luân phiên gập và ưỡn cột sống chậm rãi theo hơi thở. Bài phù hợp cho khởi động và phục hồi nhẹ.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_036', 'Thoracic Rotation', 'MOBILITY', 'BODYWEIGHT', 'CORE', 'STRETCH', ARRAY['thoracic spine', 'obliques', 'shoulders'], 'Từ tư thế quỳ hoặc nằm nghiêng, xoay ngực mở ra sau rồi trở về. Tập trung vào xoay lưng trên thay vì xoay lưng dưới.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_037', 'Hip Flexor Stretch', 'MOBILITY', 'BODYWEIGHT', 'LOWER_BODY', 'STRETCH', ARRAY['hip flexors', 'quads'], 'Quỳ một gối, đẩy hông nhẹ về trước cho đến khi cảm nhận căng ở trước hông chân sau. Giữ thân người thẳng và siết mông bên duỗi.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_038', 'Hamstring Stretch', 'MOBILITY', 'BODYWEIGHT', 'LOWER_BODY', 'STRETCH', ARRAY['hamstrings', 'calves'], 'Giữ lưng thẳng, nghiêng người từ hông về phía trước cho đến khi cảm nhận căng ở mặt sau đùi. Không cố rướn quá mức đau.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_039', 'Child''s Pose', 'MOBILITY', 'BODYWEIGHT', 'FULL_BODY', 'STRETCH', ARRAY['lats', 'lower back', 'hips'], 'Ngồi hông về gót, tay vươn dài phía trước, thả lỏng lưng và vai. Hít thở chậm để thư giãn.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_040', 'Foam Roller Thoracic Extension', 'MOBILITY', 'FOAM_ROLLER', 'UPPER_BODY', 'STRETCH', ARRAY['thoracic spine', 'chest'], 'Đặt foam roller dưới lưng trên, hỗ trợ đầu bằng tay, nhẹ nhàng duỗi ngực qua con lăn rồi trở lại. Tránh ưỡn quá nhiều ở lưng dưới.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_041', 'Jump Rope', 'CARDIO', 'BODYWEIGHT', 'FULL_BODY', 'HOLD', ARRAY['calves', 'shoulders', 'cardiovascular system'], 'Nhảy nhẹ bằng mũi chân, giữ nhịp thở đều và vai thả lỏng. Có thể chia theo interval ngắn cho người mới.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_042', 'Mountain Climber', 'STRENGTH_CARDIO', 'BODYWEIGHT', 'FULL_BODY', 'PUSH', ARRAY['core', 'shoulders', 'hip flexors', 'cardiovascular system'], 'Giữ tư thế plank cao, kéo luân phiên gối về ngực với tốc độ kiểm soát. Không để hông bật quá cao.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_043', 'Burpee', 'STRENGTH_CARDIO', 'BODYWEIGHT', 'FULL_BODY', 'PUSH', ARRAY['legs', 'chest', 'shoulders', 'core', 'cardiovascular system'], 'Từ đứng xuống plank, có thể thêm chống đẩy, sau đó bật dậy và nhảy nhẹ. Điều chỉnh tốc độ theo trình độ để giữ form tốt.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_044', 'Kettlebell Swing', 'STRENGTH_CARDIO', 'KETTLEBELL', 'FULL_BODY', 'PULL', ARRAY['glutes', 'hamstrings', 'core', 'grip'], 'Hinge hông để đưa tạ ra sau rồi búng hông mạnh đẩy tạ lên ngang ngực. Động tác chính đến từ hông, không phải nâng bằng tay.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_045', 'Medicine Ball Slam', 'STRENGTH_CARDIO', 'MEDICINE_BALL', 'FULL_BODY', 'PUSH', ARRAY['shoulders', 'lats', 'core', 'legs'], 'Nâng bóng qua đầu rồi dập mạnh xuống sàn bằng toàn thân, nhặt bóng lên và lặp lại. Giữ core chắc để bảo vệ lưng.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_046', 'Resistance Band Pull-Apart', 'STRENGTH_MOBILITY', 'RESISTANCE_BAND', 'UPPER_BODY', 'PULL', ARRAY['rear delts', 'upper back', 'posture muscles'], 'Giữ dây ngang ngực, kéo tách hai tay sang hai bên rồi trở về chậm. Bài tốt cho người ngồi nhiều và vai gù.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_047', 'Resistance Band Glute Kickback', 'STRENGTH', 'RESISTANCE_BAND', 'LOWER_BODY', 'PUSH', ARRAY['glutes', 'hamstrings'], 'Gắn dây vào cổ chân hoặc giữ cố định, đá chân ra sau bằng cơ mông rồi trở về chậm. Không xoay hông để ăn gian biên độ.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_ex_048', 'Farmer Carry', 'STRENGTH', 'DUMBBELLS', 'FULL_BODY', 'HOLD', ARRAY['grip', 'traps', 'core', 'legs'], 'Cầm tạ hai bên người, đi bộ chậm với ngực mở và bụng siết. Bài này cải thiện sức nắm, core và khả năng ổn định toàn thân.', NULL, '2026-04-08 09:00:00', '2026-04-08 09:00:00')
INSERT INTO workouts (id, user_id, name, description, date, duration, notes, created_at, updated_at) VALUES
  ('seed_wo_001', 'seed_usr_cut_001', 'Full Body A - Beginner Fat Loss', 'Buổi toàn thân thiên về kỹ thuật, nhịp vừa, phù hợp người mới cần giảm mỡ.', '2026-04-01 18:00:00', 65, 'RPE mục tiêu 6-7; nghỉ 60-90 giây ở bài phụ.', '2026-04-01 18:00:00', '2026-04-01 18:00:00'),
  ('seed_wo_002', 'seed_usr_cut_001', 'Full Body B - Beginner Fat Loss', 'Buổi toàn thân thứ hai trong tuần, thêm hinge và kéo lưng.', '2026-04-03 18:00:00', 68, 'Ưu tiên form, chưa cần tăng tạ nhanh.', '2026-04-03 18:00:00', '2026-04-03 18:00:00'),
  ('seed_wo_003', 'seed_usr_cut_001', 'Low-Impact Conditioning Circuit', 'Circuit nhẹ–vừa để tăng tiêu hao năng lượng nhưng vẫn kiểm soát kỹ thuật.', '2026-04-06 18:00:00', 42, 'Có thể đi bộ nhanh 10 phút cuối buổi.', '2026-04-06 18:00:00', '2026-04-06 18:00:00'),
  ('seed_wo_004', 'seed_usr_recomp_001', 'Lower Body Glute Focus', 'Buổi thân dưới ưu tiên mông–đùi sau, kết hợp squat phụ.', '2026-04-02 06:30:00', 72, 'RPE 7-8 ở hip thrust và RDL.', '2026-04-02 06:30:00', '2026-04-02 06:30:00'),
  ('seed_wo_005', 'seed_usr_recomp_001', 'Upper Body Balance', 'Buổi thân trên cân bằng kéo–đẩy, thêm vai sau và core.', '2026-04-04 06:30:00', 63, 'Giữ scapula ổn định ở mọi bài kéo.', '2026-04-04 06:30:00', '2026-04-04 06:30:00'),
  ('seed_wo_006', 'seed_usr_recomp_001', 'Lower + Conditioning', 'Buổi hỗn hợp để duy trì nhịp tim và tăng khối lượng vận động trong tuần.', '2026-04-07 06:30:00', 58, 'Kỹ thuật luôn ưu tiên hơn tốc độ.', '2026-04-07 06:30:00', '2026-04-07 06:30:00'),
  ('seed_wo_007', 'seed_usr_gain_001', 'Push Day - Hypertrophy', 'Tập trung ngực, vai, tay sau với volume vừa-cao.', '2026-04-01 19:30:00', 78, 'Nghỉ 2 phút ở compound chính.', '2026-04-01 19:30:00', '2026-04-01 19:30:00'),
  ('seed_wo_008', 'seed_usr_gain_001', 'Pull Day - Hypertrophy', 'Tập trung xô, lưng giữa, vai sau và tay trước.', '2026-04-03 19:30:00', 80, 'Giữ biên độ kéo đầy đủ, tránh ego lifting.', '2026-04-03 19:30:00', '2026-04-03 19:30:00'),
  ('seed_wo_009', 'seed_usr_gain_001', 'Lower Day - Strength Bias', 'Buổi thân dưới nặng hơn, ưu tiên squat và hinge.', '2026-04-05 09:00:00', 85, 'Khởi động kỹ hông và cổ chân trước bài chính.', '2026-04-05 09:00:00', '2026-04-05 09:00:00')
