  ('seed_nl_025', 'seed_usr_gain_001', '2026-04-05 07:30:00', 'PRE_WORKOUT', 'Chuối + whey + mật ong', 290, 25, 39, 1, 'Nạp nhanh trước lower day.', '2026-04-05 07:30:00', '2026-04-05 07:30:00'),
  ('seed_nl_026', 'seed_usr_gain_001', '2026-04-05 11:30:00', 'POST_WORKOUT', 'Cơm + thịt heo thăn + rau + trái cây', 840, 54, 93, 20, 'Bữa lớn sau tập chân.', '2026-04-05 11:30:00', '2026-04-05 11:30:00'),
  ('seed_nl_027', 'seed_usr_gain_001', '2026-04-05 19:30:00', 'DINNER', 'Cá ngừ áp chảo + couscous + rau củ', 710, 50, 63, 19, 'Giữ protein cao, đủ carb phục hồi.', '2026-04-05 19:30:00', '2026-04-05 19:30:00')
INSERT INTO workout_plans (id, user_id, name, description, goal, duration, days_per_week, plan, created_at, updated_at) VALUES
  ('seed_plan_001', 'seed_usr_cut_001', '8-Week Fat Loss Foundation', 'Giáo án 8 tuần cho người mới, ưu tiên toàn thân, đi bộ và thói quen ăn uống ổn định.', 'fat_loss', 8, 3, '{"phase": "foundation", "summary": "3 buổi full body/tuần + mục tiêu 7000-9000 bước/ngày.", "progression": "Khi đạt ngưỡng reps trên của mọi set với kỹ thuật tốt, tăng tải 2.5-5%.", "days": [{"day": 1, "focus": "Full Body A", "exercises": [{"name": "Goblet Squat", "sets": "3", "reps": "10-12"}, {"name": "Push-Up", "sets": "3", "reps": "8-10"}, {"name": "Lat Pulldown", "sets": "3", "reps": "10-12"}, {"name": "Glute Bridge", "sets": "3", "reps": "12-15"}, {"name": "Front Plank", "sets": "3", "duration_sec": "30-40"}]}, {"day": 2, "focus": "Full Body B", "exercises": [{"name": "Dumbbell Romanian Deadlift", "sets": "3", "reps": "8-10"}, {"name": "Step-Up", "sets": "3", "reps": "10/leg"}, {"name": "Seated Cable Row", "sets": "3", "reps": "10-12"}, {"name": "Seated Dumbbell Shoulder Press", "sets": "3", "reps": "8-10"}, {"name": "Dead Bug", "sets": "3", "reps": "10/side"}]}, {"day": 3, "focus": "Conditioning + Mobility", "exercises": [{"name": "Jump Rope", "sets": "5", "duration_sec": "45-60"}, {"name": "Mountain Climber", "sets": "4", "duration_sec": "20-30"}, {"name": "Resistance Band Pull-Apart", "sets": "3", "reps": "15"}, {"name": "Child''s Pose", "sets": "2", "duration_sec": "45"}]}], "nutrition_notes": ["Ưu tiên protein mỗi bữa", "Giảm đồ uống có đường", "Ăn rau trong ít nhất 2 bữa chính/ngày"]}'::jsonb, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_plan_002', 'seed_usr_recomp_001', '6-Week Recomp Lower Emphasis', 'Chương trình 6 tuần cho người đã có nền tảng nhẹ, tập trung thân dưới và giữ vóc dáng.', 'recomp', 6, 3, '{"phase": "recomposition", "summary": "2 buổi lower + 1 buổi upper/tuần, cardio ngắn sau tập 1-2 lần.", "progression": "Tăng reps trước, tăng tải sau. Giữ RPE khoảng 7-8 ở bài chính.", "days": [{"day": 1, "focus": "Lower Glutes", "exercises": [{"name": "Barbell Hip Thrust", "sets": "4", "reps": "8"}, {"name": "Dumbbell Romanian Deadlift", "sets": "4", "reps": "10"}, {"name": "Walking Lunge", "sets": "3", "reps": "10/leg"}, {"name": "Leg Curl", "sets": "3", "reps": "12"}, {"name": "Side Plank", "sets": "3", "duration_sec": "30-40"}]}, {"day": 2, "focus": "Upper Balance", "exercises": [{"name": "Incline Dumbbell Press", "sets": "4", "reps": "8"}, {"name": "One-Arm Dumbbell Row", "sets": "4", "reps": "10/side"}, {"name": "Face Pull", "sets": "3", "reps": "15"}, {"name": "Dumbbell Lateral Raise", "sets": "3", "reps": "15"}, {"name": "Dead Bug", "sets": "3", "reps": "10/side"}]}, {"day": 3, "focus": "Lower + Conditioning", "exercises": [{"name": "Goblet Squat", "sets": "3", "reps": "12"}, {"name": "Step-Up", "sets": "3", "reps": "12/leg"}, {"name": "Kettlebell Swing", "sets": "6", "duration_sec": "20"}, {"name": "Mountain Climber", "sets": "4", "duration_sec": "30"}]}], "nutrition_notes": ["Duy trì protein cao", "Carb quanh buổi tập", "Kiểm tra số đo và ảnh mỗi 2 tuần"]}'::jsonb, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_plan_003', 'seed_usr_gain_001', '12-Week Hypertrophy Push Pull Legs', 'Giáo án 12 tuần tăng cơ cho người trung cấp, nhấn mạnh progressive overload và kiểm soát volume.', 'muscle_gain', 12, 5, '{"phase": "hypertrophy", "summary": "PPL 5 buổi/tuần với 1-2 buổi phụ, surplus nhẹ và ngủ đủ.", "progression": "Ở bài compound, tăng 2.5-5 kg khi hoàn thành mức reps mục tiêu ở tất cả set. Bài phụ tăng 1-2 reps trước.", "days": [{"day": 1, "focus": "Push Heavy", "exercises": [{"name": "Barbell Bench Press", "sets": "4", "reps": "5-6"}, {"name": "Incline Dumbbell Press", "sets": "4", "reps": "8"}, {"name": "Seated Dumbbell Shoulder Press", "sets": "4", "reps": "8"}, {"name": "Cable Chest Fly", "sets": "3", "reps": "12"}, {"name": "Triceps Rope Pushdown", "sets": "3", "reps": "12"}]}, {"day": 2, "focus": "Pull Heavy", "exercises": [{"name": "Barbell Bent-Over Row", "sets": "4", "reps": "6-8"}, {"name": "Lat Pulldown", "sets": "4", "reps": "8-10"}, {"name": "Seated Cable Row", "sets": "3", "reps": "10"}, {"name": "Face Pull", "sets": "3", "reps": "15"}, {"name": "Hammer Curl", "sets": "3", "reps": "12"}]}, {"day": 3, "focus": "Legs Heavy", "exercises": [{"name": "Barbell Back Squat", "sets": "5", "reps": "5"}, {"name": "Romanian Deadlift", "sets": "4", "reps": "6"}, {"name": "Leg Press", "sets": "3", "reps": "12"}, {"name": "Leg Curl", "sets": "3", "reps": "12"}, {"name": "Standing Calf Raise", "sets": "4", "reps": "15"}]}], "nutrition_notes": ["Surplus nhẹ 200-300 kcal", "Protein phân đều 3-5 bữa", "Theo dõi cân nặng trung bình tuần"]}'::jsonb, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_plan_004', 'seed_usr_cut_001', '4-Week Home Dumbbell Reset', 'Kế hoạch ngắn cho người tập ở nhà với dumbbell và bodyweight.', 'general_fitness', 4, 4, '{"phase": "home_training", "summary": "4 buổi/tuần, mỗi buổi 35-45 phút.", "progression": "Thêm 1-2 reps hoặc tăng nhịp chậm ở eccentric khi chưa có tạ nặng hơn.", "days": [{"day": 1, "focus": "Upper", "exercises": [{"name": "Incline Push-Up", "sets": "4", "reps": "10-15"}, {"name": "One-Arm Dumbbell Row", "sets": "4", "reps": "12/side"}, {"name": "Dumbbell Lateral Raise", "sets": "3", "reps": "15"}]}, {"day": 2, "focus": "Lower", "exercises": [{"name": "Goblet Squat", "sets": "4", "reps": "12"}, {"name": "Dumbbell Romanian Deadlift", "sets": "4", "reps": "12"}, {"name": "Glute Bridge", "sets": "3", "reps": "20"}]}, {"day": 3, "focus": "Core + Conditioning", "exercises": [{"name": "Front Plank", "sets": "3", "duration_sec": "40"}, {"name": "Mountain Climber", "sets": "5", "duration_sec": "30"}, {"name": "Jump Rope", "sets": "5", "duration_sec": "60"}]}]}'::jsonb, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_plan_005', 'seed_usr_recomp_001', '6-Week Mobility & Core Restore', 'Kế hoạch phục hồi chủ động cho giai đoạn stress cao hoặc mới quay lại tập.', 'recovery_mobility', 6, 3, '{"phase": "restore", "summary": "3 buổi/tuần, nhấn mạnh mobility, core và bước đi mỗi ngày.", "progression": "Tăng thời gian giữ và biên độ có kiểm soát, không tăng độ khó quá nhanh.", "days": [{"day": 1, "focus": "Core Stability", "exercises": [{"name": "Dead Bug", "sets": "3", "reps": "8/side"}, {"name": "Bird Dog", "sets": "3", "reps": "8/side"}, {"name": "Front Plank", "sets": "3", "duration_sec": "20-30"}]}, {"day": 2, "focus": "Mobility", "exercises": [{"name": "Cat-Cow", "sets": "2", "reps": "8"}, {"name": "Thoracic Rotation", "sets": "2", "reps": "8/side"}, {"name": "Hip Flexor Stretch", "sets": "2", "duration_sec": "30/side"}, {"name": "Hamstring Stretch", "sets": "2", "duration_sec": "30/side"}]}, {"day": 3, "focus": "Light Full Body", "exercises": [{"name": "Bodyweight Squat", "sets": "3", "reps": "12"}, {"name": "Resistance Band Pull-Apart", "sets": "3", "reps": "15"}, {"name": "Child''s Pose", "sets": "2", "duration_sec": "45"}]}]}'::jsonb, '2026-04-08 09:00:00', '2026-04-08 09:00:00'),
  ('seed_plan_006', 'seed_usr_gain_001', '8-Week Strength Base 4-Day', 'Chương trình 4 buổi để củng cố sức mạnh nền trước khi vào block hypertrophy cao hơn.', 'strength_base', 8, 4, '{"phase": "strength", "summary": "Upper/Lower 4 buổi, compound làm chính, volume vừa phải.", "progression": "Mục tiêu tăng tạ đều nhưng giữ ít nhất 1-2 reps dự trữ ở đa số set.", "days": [{"day": 1, "focus": "Upper 1", "exercises": [{"name": "Barbell Bench Press", "sets": "5", "reps": "5"}, {"name": "Barbell Bent-Over Row", "sets": "5", "reps": "5"}, {"name": "Face Pull", "sets": "3", "reps": "15"}]}, {"day": 2, "focus": "Lower 1", "exercises": [{"name": "Barbell Back Squat", "sets": "5", "reps": "5"}, {"name": "Romanian Deadlift", "sets": "4", "reps": "6"}, {"name": "Standing Calf Raise", "sets": "4", "reps": "12"}]}, {"day": 3, "focus": "Upper 2", "exercises": [{"name": "Seated Dumbbell Shoulder Press", "sets": "4", "reps": "6-8"}, {"name": "Lat Pulldown", "sets": "4", "reps": "8"}, {"name": "Hammer Curl", "sets": "3", "reps": "10"}]}, {"day": 4, "focus": "Lower 2", "exercises": [{"name": "Leg Press", "sets": "4", "reps": "10"}, {"name": "Walking Lunge", "sets": "3", "reps": "8/leg"}, {"name": "Front Plank", "sets": "3", "duration_sec": "45"}]}]}'::jsonb, '2026-04-08 09:00:00', '2026-04-08 09:00:00')
INSERT INTO conversations (id, user_id, question, answer, model_used, response_time, relevance, relevance_explanation, prompt_tokens, completion_tokens, total_tokens, cost, feedback, feedback_timestamp, created_at) VALUES
  ('seed_conv_001', NULL, 'Progressive overload là gì?', 'Progressive overload là nguyên tắc tăng dần áp lực tập luyện theo thời gian để cơ thể tiếp tục thích nghi. Bạn có thể tăng tạ, thêm reps, thêm set, cải thiện kỹ thuật hoặc rút ngắn thời gian nghỉ, nhưng nên thay đổi có kiểm soát và vẫn giữ form chuẩn.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:00:00'),
  ('seed_conv_002', NULL, 'Người mới nên tập mấy buổi mỗi tuần?', 'Người mới thường phù hợp với 2-4 buổi kháng lực mỗi tuần. Điều quan trọng không chỉ là số buổi mà là tổng khối lượng tập vừa đủ, thời gian phục hồi và khả năng duy trì đều trong nhiều tuần.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:05:00'),
  ('seed_conv_003', NULL, 'Có cần khởi động trước khi tập không?', 'Có. Khởi động giúp tăng nhiệt cơ thể, cải thiện phạm vi chuyển động và chuẩn bị hệ thần kinh cho bài chính. Một buổi khởi động tốt thường gồm 5-10 phút vận động nhẹ, 1-2 bài mobility liên quan và vài set làm quen với tải thấp.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:10:00'),
  ('seed_conv_004', NULL, 'DOMS có phải là dấu hiệu của buổi tập tốt?', 'Không hẳn. DOMS chỉ là đau mỏi cơ xuất hiện sau tập, thường do cơ thể chưa quen mức tải hoặc biên độ mới. Một buổi tập tốt được đánh giá tốt hơn qua tiến bộ dài hạn về hiệu suất, kỹ thuật và khả năng phục hồi, không phải chỉ bằng cảm giác đau.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:15:00'),
  ('seed_conv_005', NULL, 'Giảm mỡ có cần bỏ hoàn toàn tinh bột không?', 'Không cần. Giảm mỡ chủ yếu phụ thuộc vào việc duy trì mức năng lượng nạp vào thấp hơn mức tiêu hao trong thời gian đủ dài. Tinh bột vẫn hữu ích cho hiệu suất tập luyện và phục hồi; quan trọng là chọn khẩu phần phù hợp và ưu tiên nguồn thực phẩm ít chế biến.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:20:00'),
  ('seed_conv_006', NULL, 'Protein nên chia như thế nào trong ngày?', 'Thực tế hơn cả là phân bổ protein khá đều vào 3-5 bữa trong ngày thay vì dồn toàn bộ vào một bữa. Cách này giúp dễ đạt tổng lượng protein mục tiêu và hỗ trợ phục hồi cơ bắp tốt hơn.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:25:00'),
  ('seed_conv_007', NULL, 'Nên nghỉ bao lâu giữa các set?', 'Bài compound nặng thường cần nghỉ khoảng 2-3 phút để giữ hiệu suất. Bài phụ hoặc isolation thường nghỉ ngắn hơn, khoảng 45-90 giây. Mục tiêu là nghỉ đủ để giữ chất lượng set tiếp theo, không chỉ nghỉ theo thói quen.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:30:00'),
  ('seed_conv_008', NULL, 'Khi nào nên deload?', 'Deload thường phù hợp khi bạn tích lũy mệt mỏi rõ rệt: hiệu suất giảm liên tiếp, đau mỏi kéo dài, khó ngủ hoặc cảm giác nặng nề bất thường. Deload không có nghĩa là nghỉ hẳn; bạn có thể giảm tải, giảm set hoặc giảm cường độ trong khoảng 5-7 ngày.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:35:00'),
  ('seed_conv_009', NULL, 'Tập cardio có làm mất cơ không?', 'Cardio không tự động làm mất cơ. Vấn đề thường đến từ việc cardio quá nhiều trong khi ăn quá ít, ngủ kém và vẫn cố duy trì khối lượng tập tạ cao. Khi phối hợp hợp lý, cardio còn giúp cải thiện tim mạch và khả năng phục hồi chung.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:40:00'),
  ('seed_conv_010', NULL, 'Creatine có đáng dùng không?', 'Creatine monohydrate là một trong những supplement được nghiên cứu nhiều nhất cho hiệu suất sức mạnh và công suất ngắn hạn. Tuy nhiên, supplement chỉ là phần nhỏ; nền tảng vẫn là tập luyện đúng, ăn đủ và ngủ đủ.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:45:00'),
  ('seed_conv_011', NULL, 'Ngủ ảnh hưởng thế nào đến tăng cơ và giảm mỡ?', 'Ngủ kém thường làm giảm hiệu suất tập luyện, tăng cảm giác đói, làm việc phục hồi cơ bắp kém hơn và khiến việc bám kế hoạch ăn uống khó hơn. Với đa số người trưởng thành, ngủ đều và đủ giờ là một biến số rất quan trọng nhưng hay bị xem nhẹ.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:50:00'),
  ('seed_conv_012', NULL, 'Khi nào nên dừng bài tập vì đau?', 'Nếu chỉ là mỏi cơ nhẹ và kỹ thuật vẫn ổn, bạn có thể tiếp tục có kiểm soát. Nhưng nếu xuất hiện đau nhói, đau tăng theo từng rep, tê lan hoặc cảm giác mất ổn định, nên dừng bài tập đó và cân nhắc đánh giá chuyên môn y tế nếu triệu chứng kéo dài.', 'manual_seed_v1', 0.05, 'HIGH', 'Curated knowledge seed', 0, 0, 0, 0, NULL, NULL, '2026-04-01 09:55:00')
